-- Reporting views used by student, teacher and school dashboards.
CREATE OR REPLACE VIEW v_student_progress AS SELECT se.id AS enrollment_id,se.student_id,p.display_name AS student_name,se.class_id,c.name AS class_name,c.organization_id,se.book_id,b.title_en AS book_title,se.status AS enrollment_status,COUNT(DISTINCT bp.unit_id) AS units_touched,COALESCE(ROUND(AVG(bp.completion_percent),1),0) AS avg_unit_completion,COUNT(DISTINCT aa.activity_id) FILTER(WHERE aa.completion_status='completed') AS activities_completed,COALESCE(ROUND(AVG(aa.score) FILTER(WHERE aa.score IS NOT NULL),1),0) AS avg_score,MAX(GREATEST(COALESCE(bp.last_activity_at,to_timestamp(0)),COALESCE(aa.submitted_at,to_timestamp(0)))) AS last_active_at FROM student_enrollments se JOIN profiles p ON p.id=se.student_id LEFT JOIN classes c ON c.id=se.class_id LEFT JOIN books b ON b.id=se.book_id LEFT JOIN book_progress bp ON bp.enrollment_id=se.id LEFT JOIN activity_attempts aa ON aa.enrollment_id=se.id GROUP BY se.id,se.student_id,p.display_name,se.class_id,c.name,c.organization_id,se.book_id,b.title_en,se.status;
CREATE OR REPLACE VIEW v_class_summary AS SELECT c.id AS class_id,c.organization_id,c.name AS class_name,c.level_label,c.status,COUNT(DISTINCT cm.student_id) FILTER(WHERE cm.status='active') AS active_students,COUNT(DISTINCT ta.teacher_id) AS teacher_count,COUNT(DISTINCT a.id) AS assignment_count,COUNT(DISTINCT s.id) FILTER(WHERE s.status='submitted') AS submissions_received FROM classes c LEFT JOIN class_memberships cm ON cm.class_id=c.id LEFT JOIN teacher_assignments ta ON ta.class_id=c.id LEFT JOIN assignments a ON a.class_id=c.id LEFT JOIN submissions s ON s.assignment_id=a.id GROUP BY c.id,c.organization_id,c.name,c.level_label,c.status;
CREATE OR REPLACE VIEW v_org_dashboard AS SELECT o.id AS organization_id,o.name AS organization_name,o.organization_type,COUNT(DISTINCT c.id) FILTER(WHERE c.status='active') AS active_classes,COUNT(DISTINCT om.profile_id) FILTER(WHERE om.role='teacher' AND om.status='active') AS teacher_count,COUNT(DISTINCT om.profile_id) FILTER(WHERE om.role='student' AND om.status='active') AS student_count,COUNT(DISTINCT ii.id) FILTER(WHERE ii.status='active') AS active_integrations FROM organizations o LEFT JOIN classes c ON c.organization_id=o.id LEFT JOIN organization_memberships om ON om.organization_id=o.id LEFT JOIN integration_installations ii ON ii.organization_id=o.id GROUP BY o.id,o.name,o.organization_type;
CREATE OR REPLACE VIEW v_integration_health AS SELECT ii.id AS installation_id,ii.organization_id,ip.slug AS provider_slug,ip.display_name AS provider_name,ip.category,ii.status,ii.health_state,ii.last_health_at,ii.last_error FROM integration_installations ii JOIN integration_providers ip ON ip.id=ii.provider_id;
